insert into game.seasons (slug, title, content)
values ('season-1', 'Last Login — Season 1: Without a Trace', '{"slug":"season-1","title":"Last Login — Season 1: Without a Trace","clock":{"now":"1997-10-18T21:47:00"},"computer":{"owner":"Casey Taylor","loginUser":"casey","loginTargetId":"login.casey","loginHint":"moms flower + the year","saverText":"junebug","imScreenname":"SunflwrC81","bootWarning":["WARNING: This computer was not shut down properly.","Last session ended:  10/11/97  2:31 AM"],"dosVolume":{"label":"CASEY","serial":"2141-1011"}},"passwords":{"login.casey":{"password":"sunflower97"}},"wallpaper":"teal","homeUrl":"www.searchhound.net","maxPasswordAttempts":6,"lockoutSeconds":90,"discoveries":[{"id":"the-meeting","title":"The meeting","description":"Casey told Sadie she was meeting someone the night of the 10th — down by the river — and wouldn’t say who. Nobody in her life knows who."},{"id":"stolen-intimacy","title":"Stolen intimacy","description":"GhostBridge proved himself with things from inside Casey’s private world — words nobody outside it could know. He didn’t earn her trust. He read it."},{"id":"chads-window","title":"Chad’s window","description":"Chad spent that whole week begging to know who Casey was talking to online — and spent the night of the 10th on a barstool at Gene’s. You don’t get jealous of yourself."},{"id":"the-clean-truck","title":"The clean dark truck","description":"Frank saw a quiet, clean 4x4 stop at the bend that night. Chad’s lifted truck can be heard three streets away — and Frank knows every engine in this county."},{"id":"the-pipeline","title":"The pipeline","description":"Dr. Sparks writes them. Value-Med fills them. Cash, strangers’ initials, license plates from three counties away. That’s what Casey found — and what somebody needed her not to have found."},{"id":"who-shaped","title":"A familiar shape","description":"Rebecca Wright’s first husband used to read her mail and answer it in her own voice. She recognizes the pattern. Now so do you."},{"id":"the-house","title":"The house","description":"Someone used this computer at 2:14 AM on October 11 — hours after Casey disappeared. They read her diary, and then they deleted it. They didn’t break in. They were already home.","endsDemo":true}],"buddies":[{"screenname":"sadiedraws77","alias":"sadie","group":"Buddies","status":"online","conversationId":"im.sadie"},{"screenname":"AngelJx","alias":"angel","group":"Buddies","status":"away","awayMessage":"grounded. 4ever apparently.","conversationId":"im.angel"},{"screenname":"BigChad4x4","alias":"chad","group":"Buddies","status":"offline"},{"screenname":"GhostBridge","group":"Buddies","status":"offline","requires":{"discovery":"stolen-intimacy"},"overrides":[{"requires":{"discovery":"the-house"},"status":"online"},{"requires":{"flag":"ghost-signoff"},"status":"offline"}]}],"conversations":[{"screenname":"sadiedraws77","opener":["casey???","casey oh my god. ur online. say something","…you’re not her. are you. she never just sits there."],"prompts":[{"id":"intro","text":"this isn’t casey. i’m at her computer, trying to find out what happened.","setFlags":{"sadie-talking":true},"discover":["the-meeting"],"replies":["ok.","ok. i don’t know who you are. police, family, whoever.","if you’re at her desk you’re in her HOUSE. i’m deciding right now not to think too hard about that. because nobody else is LOOKING. the police think she ran off or fell in the river and they’re wrong both times.","so listen. thursday night, on her porch, she told me she was meeting someone friday. down by the river. she wouldn’t say who. “it’s a whole thing, i’ll tell you saturday.” she was excited and scared at the same time.","she tells me everything. since second grade. and she wouldn’t tell me this. that’s the part that keeps me up."]},{"id":"online-guy","text":"did she say anything about who she was talking to online?","requires":{"all":[{"flag":"sadie-talking"},{"discovery":"the-meeting"}]},"replies":["no. and i ASKED. she’d go all careful. “i want to be sure first.”","chad was losing his mind about it. kept cornering me in the hall like i was hiding a guy in my backpack.","whoever it was, she didn’t act like it was romantic. she acted like it was important. those are different faces on casey."]},{"id":"frank","text":"could it have been her dad she was meeting?","requires":{"all":[{"flag":"sadie-talking"},{"discovery":"chads-window"}]},"discover":["the-clean-truck"],"replies":["frank? no. and i can sort of prove it.","i biked out to his trailer wednesday. everybody acts like he’s a monster. he’s just sad, and drunk, and he skips rocks at the river alone like it still counts.","he told me something he won’t tell the sheriff. friday night, around ten, he watched a vehicle come up the fire road and stop at the bend. dark 4x4. CLEAN. quiet. sat there with the lights off.","he said “it wasn’t the daniels boy. that truck of his you can hear from the church.” he knows every engine in this county. it’s his one thing.","somebody who washes his car was at the bend that night. write that down, whoever you are."]},{"id":"vigil","text":"has anyone strange been around since she disappeared?","requires":{"all":[{"flag":"sadie-talking"},{"discovery":"the-pipeline"}]},"discover":["who-shaped"],"replies":["how did you— ok. yes. one thing.","friday at st mark’s a woman stood at the very back. older. nice coat. not from here. and after, she came up to ME. of everybody.","she asked if casey had been “writing to someone who sounded exactly right.” word for word. EXACTLY RIGHT.","she said to watch casey’s mail, and if a letter ever comes from an r. wright — believe it. then she left before the last hymn.","i didn’t understand it then. i think maybe you do."]},{"id":"about-her","text":"what was casey like?","requires":{"flag":"sadie-talking"},"replies":["the kind of person who keeps the drawing you made her in second grade.","she has a code word with me. for if things ever got Actually Bad. i’m not telling you what it is. it’s ours.","just don’t stop halfway, ok? whatever you find. she wouldn’t."]}]},{"screenname":"AngelJx","opener":["Auto response from AngelJx: grounded. 4ever apparently.","ok i’m actually here. if my mom hears typing i’m dead. who is this. casey’s mom??"],"prompts":[{"id":"friday","text":"i’m looking through casey’s computer. what really happened friday?","setFlags":{"angel-talking":true},"replies":["did sadie put you up to this. whatever. i already told the police the real version, ok.","we were at the back lot behind gene’s. wine coolers. my cousin got them for us. i said i dropped her home at 8 instead of 7 because of his JOB, and now the whole town acts like i buried her.","i dropped her at 7. i WATCHED her walk in her own front door. whatever happened to casey happened after her own front door. nobody wants to think about that. but it’s true."]},{"id":"chain-letter","text":"she kept your chain letter. it’s still on the computer.","requires":{"flag":"angel-talking"},"replies":["the good luck angel?? she SAVED it???","ok. i’m crying at the computer desk. great. cool.","when she comes back i’m sending her ten more. tell her that. word for word."]}]},{"screenname":"GhostBridge","requires":{"discovery":"the-house"},"opener":["you’re up late."],"prompts":[{"id":"pretend","text":"couldn’t sleep.","replies":["no. i don’t imagine you could.","whoever you are."]},{"id":"who","text":"who is this?","replies":["a friend of the family."]},{"id":"junebug","text":"junebug.","replies":[],"signOff":true,"setFlags":{"ghost-signoff":true}}]}],"items":[{"id":"folder.c","kind":"folder","name":"Casey (C:)","icon":"drive","meta":{"path":"C:\\","desktop":{"x":24,"y":24}}},{"id":"folder.my-documents","kind":"folder","name":"My Documents","icon":"folder-docs","parentId":"folder.c","meta":{"path":"C:\\My Documents","modifiedAt":"1997-10-10","desktop":{"x":24,"y":120}}},{"id":"folder.pictures","kind":"folder","name":"Pictures","icon":"folder-pics","parentId":"folder.c","meta":{"path":"C:\\Pictures","modifiedAt":"1997-09-28","desktop":{"x":24,"y":216}}},{"id":"folder.downloads","kind":"folder","name":"Downloads","icon":"folder","parentId":"folder.c","meta":{"path":"C:\\Downloads","modifiedAt":"1997-10-06"}},{"id":"folder.programs","kind":"folder","name":"Program Files","icon":"folder","parentId":"folder.c","meta":{"path":"C:\\Program Files","modifiedAt":"1997-08-14"}},{"id":"pf.netvoyager","kind":"shortcut","name":"NetVoyager 3.0","icon":"browser","parentId":"folder.programs","meta":{"appId":"browser","modifiedAt":"1997-06-02"}},{"id":"pf.chat","kind":"shortcut","name":"Chat","icon":"im-app","parentId":"folder.programs","meta":{"appId":"buddyline","modifiedAt":"1997-05-11"}},{"id":"pf.mail","kind":"shortcut","name":"Mail","icon":"mail-app","parentId":"folder.programs","meta":{"appId":"mail","modifiedAt":"1997-03-28"}},{"id":"pf.notepad","kind":"shortcut","name":"Notepad","icon":"notepad","parentId":"folder.programs","meta":{"appId":"notepad","modifiedAt":"1996-11-20"}},{"id":"pf.pictures","kind":"shortcut","name":"Picture Viewer","icon":"photo","parentId":"folder.programs","meta":{"appId":"photos","modifiedAt":"1996-11-20"}},{"id":"pf.calculator","kind":"shortcut","name":"Calculator","icon":"calc","parentId":"folder.programs","meta":{"appId":"calculator","modifiedAt":"1996-11-20"}},{"id":"pf.calendar","kind":"shortcut","name":"Calendar","icon":"calendar","parentId":"folder.programs","meta":{"appId":"calendar","modifiedAt":"1996-11-20"}},{"id":"pf.solitaire","kind":"shortcut","name":"Solitaire","icon":"game","parentId":"folder.programs","meta":{"appId":"solitaire","modifiedAt":"1996-11-20"}},{"id":"pf.minefield","kind":"shortcut","name":"Minefield","icon":"mine","parentId":"folder.programs","meta":{"appId":"minefield","modifiedAt":"1996-11-20"}},{"id":"pf.paint","kind":"shortcut","name":"Paint","icon":"paint","parentId":"folder.programs","meta":{"appId":"paintbox","modifiedAt":"1996-11-20"}},{"id":"pf.cdplayer","kind":"shortcut","name":"CD Player","icon":"cd","parentId":"folder.programs","meta":{"appId":"discdeck","modifiedAt":"1996-11-20"}},{"id":"pf.clock","kind":"shortcut","name":"Clock","icon":"clock","parentId":"folder.programs","meta":{"appId":"clock","modifiedAt":"1996-11-20"}},{"id":"pf.display","kind":"shortcut","name":"Display","icon":"display","parentId":"folder.programs","meta":{"appId":"display","modifiedAt":"1996-11-20"}},{"id":"pf.sysmon","kind":"shortcut","name":"System Monitor","icon":"sysmon","parentId":"folder.programs","meta":{"appId":"sysmon","modifiedAt":"1996-11-20"}},{"id":"pf.dialup","kind":"shortcut","name":"Dial-Up Networking","icon":"dialup","parentId":"folder.programs","meta":{"appId":"dialup","modifiedAt":"1997-06-30"}},{"id":"folder.school","kind":"folder","name":"School","icon":"folder","parentId":"folder.my-documents","meta":{"path":"C:\\My Documents\\School","modifiedAt":"1997-10-08"}},{"id":"folder.personal","kind":"folder","name":"personal stuff","icon":"folder","parentId":"folder.my-documents","meta":{"path":"C:\\My Documents\\personal stuff","modifiedAt":"1997-10-09"}},{"id":"folder.writing","kind":"folder","name":"Writing!!","icon":"folder","parentId":"folder.my-documents","meta":{"path":"C:\\My Documents\\Writing!!","modifiedAt":"1997-09-30"}},{"id":"file.minewars-report","kind":"document","name":"wv history - mine wars essay.txt","icon":"doc","parentId":"folder.school","meta":{"createdAt":"1997-10-02","modifiedAt":"1997-10-08","sizeKb":6},"body":{"text":"THE MINE WARS AND WHAT THEY COST\nCasey Taylor, Per. 3, Mr. Estep\n\nIn 1921, ten thousand miners marched on Blair Mountain because the\ncompanies owned the houses, the stores, the scales that weighed the\ncoal, and the men who did the weighing. When everything in a town runs\nthrough one set of hands, the town stops being able to say no.\n\n(NOTE TO SELF: estep wants \"relevance to today.\" careful how i word\nthat one.)\n\nSources:\n- library, WV history shelf (all 4 books)\n- grandpa taylor''s stories (counts as a primary source??)\n- searchhound \"blair mountain\" (mostly junk)"}},{"id":"file.algebra","kind":"document","name":"algebra_hw_oct6.txt","icon":"doc","parentId":"folder.school","meta":{"createdAt":"1997-10-06","modifiedAt":"1997-10-06","sizeKb":1},"body":{"text":"p.114 #1-19 odd\n3) x = 7\n5) x = -2\n7) x = 4/3 ?? check w/ sadie\n9) skipped, ask in class\n13) no idea. NO idea.\n\nquiz friday (the 10th) — STUDY THURS"}},{"id":"file.english-journal","kind":"document","name":"english journal wk4.txt","icon":"doc","parentId":"folder.school","meta":{"createdAt":"1997-09-29","modifiedAt":"1997-09-29","sizeKb":2},"body":{"text":"English 11 — journal, week 4\nPrompt: \"Describe a place that matters to you.\"\n\nThe bend on the river out Route 9, I guess. Everybody swims at the\npark side but if you take the fire road past mile marker 6 there''s a\nspot where the bank opens up and the water goes slow and green. Dad\ntaught me to skip rocks there before everything. He can still do\neleven. My record is six.\n\nIt''s quiet in a way the rest of this town isn''t. Nobody watches you\nthere.\n\n(ms. combs wrote \"lovely detail\" on my last one so i''m keeping the\nnature thing going. easy A.)"}},{"id":"file.ledger-copy","kind":"document","name":"wv history extra notes.txt","icon":"doc","parentId":"folder.school","meta":{"createdAt":"1997-10-05","modifiedAt":"1997-10-05","sizeKb":2},"requires":{"discovery":"the-clean-truck"},"onOpen":{"discover":["the-pipeline"]},"body":{"text":"[not history notes. if you found this you were looking.]\n\ncopied from the page in the den desk, 10/5. exact as i could.\n\n  9/02   T.M.   3   $150   V-M   ok\n  9/06   R.C.   3   $180   V-M   ok\n  9/12   D.K.   4   $240   V-M   ok - W.S. sat hrs\n  9/19   T.M.   3   $150   V-M   ok\n  9/26   L.B.   6   $360   V-M   W.S. — \"no more walk-ins\"\n  10/03  R.C.   3   $180   V-M   ok\n\nV-M is the pharmacy. W.S. — there is one W.S. in this town and\neverybody calls him Win.\n\nthe \"patients\" park out front of sparks'' office with license plates\nfrom three counties away. saturday hours. cash.\n\ni put the real page back. this is my copy. if something happens to\nthe page, this is still here.\n\nif something happens to ME — sadie, it''s in the SCHOOL folder,\nbecause nobody ever looks at homework."}},{"id":"file.lists","kind":"document","name":"lists.txt","icon":"doc","parentId":"folder.personal","meta":{"createdAt":"1997-08-19","modifiedAt":"1997-10-04","sizeKb":1},"body":{"text":"MIXTAPE FOR SADIE (side A)\n1. solar flare - static heart\n2. velvet june - anywhere but here\n3. that song from the radio tues (find out name)\n4. solar flare - carousel\n5. something slow for the end. undecided.\n\nTHINGS I NEED\n- new batteries for the discman\n- blank tapes (maxell, NOT the cheap ones)\n- $$ for homecoming. ask mom. beg mom.\n\nPEOPLE WHO OWE ME\n- angel $4 (movie)\n- nobody else. this town is broke."}},{"id":"file.songs","kind":"document","name":"songs i wrote (private).txt","icon":"doc","parentId":"folder.personal","meta":{"createdAt":"1997-07-11","modifiedAt":"1997-09-21","sizeKb":2},"body":{"text":"** if anyone reads this i will literally die **\n\n\"ROUTE 9\"\ngreen water going slow / six skips and the seventh sank\nyou said count again, kiddo / i''ve been counting since you left\n\n(too sad? it''s about dad. everything''s about somebody.)\n\n\"UNTITLED 3\"\nthe porch light stays on all night now\nmoths keep faith better than people do\n\n(chorus needs work. everything needs work.)"}},{"id":"file.riverstory","kind":"document","name":"story - the ferry keeper (unfinished).txt","icon":"doc","parentId":"folder.writing","meta":{"createdAt":"1997-09-14","modifiedAt":"1997-09-30","sizeKb":4},"body":{"text":"THE FERRY KEEPER (working title)\nby C. Taylor\n\nMarta had run the cable ferry for eleven years, and in eleven years\nshe had learned that the river does not take people. People give\nthemselves to it, a little at a time, in ways nobody notices until\nthe giving is done.\n\nThe boy arrived on a Tuesday, soaked through, holding a shoebox.\n\"There''s a bird in here,\" he said. \"It''s not doing so hot.\"\n\n[chapter 2 goes here. marta fixes the bird. the bird is NOT a\nmetaphor ms. combs, sometimes a bird is a bird]"}},{"id":"file.gb-log-oct8","kind":"document","name":"poem drafts 2.txt","icon":"doc","parentId":"folder.writing","meta":{"createdAt":"1997-10-08","modifiedAt":"1997-10-08","sizeKb":2},"requires":{"discovery":"the-meeting"},"onOpen":{"discover":["stolen-intimacy"]},"body":{"text":"[not poems. pasted 10/8. if i''m ever wrong about him, this is\nhow you''ll know. he doesn''t just know ABOUT me. he knows my STUFF.]\n\nGhostBridge: you still don''t trust me\nSunflwrC81: i don''t KNOW you. big difference\nGhostBridge: you know me better than you think. \"the porch light\n  stays on all night now. moths keep faith better than people do.\"\nSunflwrC81: ...\nSunflwrC81: where did you get that\nGhostBridge: you wrote it. it''s good. you should finish the chorus.\nSunflwrC81: that file is ON MY COMPUTER. it''s not on my page. it''s\n  not ANYWHERE\nGhostBridge: casey. calm down. people who do what i do have ways of\n  knowing things. it''s why i can help you when nobody else can.\nGhostBridge: your dad can still skip eleven, right? you got to six.\nSunflwrC81: stop\nGhostBridge: i''m not trying to scare you. i''m showing you i''m real.\nSunflwrC81: ok. you''re real. that''s the part that scares me"}},{"id":"file.tourdates","kind":"document","name":"solarflare_tourdates.txt","icon":"doc","parentId":"folder.downloads","meta":{"createdAt":"1997-10-06","modifiedAt":"1997-10-06","sizeKb":1},"body":{"text":"SOLAR FLARE — \"STATIC HEART\" TOUR — FALL 97\n(from the fan club page. saved so i stop losing it)\n\nOCT 24 - CHARLESTON, CIVIC HALL\nOCT 26 - HUNTINGTON, THE ARMORY  <-- 1 HR AWAY. POSSIBLE??\nNOV 01 - MORGANTOWN, FAIRGROUNDS\nNOV 03 - ROANOKE, STATE THEATER\n\nall ages except roanoke. tickets $12 + service charge (robbery)"}},{"id":"file.chainletter-dl","kind":"document","name":"GOOD_LUCK_ANGEL.txt","icon":"doc","parentId":"folder.downloads","meta":{"createdAt":"1997-09-25","modifiedAt":"1997-09-25","sizeKb":2},"body":{"text":"THIS IS THE GOOD LUCK ANGEL !!! (>o<)\n\nSend her to 10 friends within 24 HOURS and something WONDERFUL will\nhappen to you by the weekend. Marcy T. of Ohio deleted this message\nand her modem was struck by LIGHTNING. Do not risk it!!!\n\n(angel sent me this because of her NAME. i am keeping it purely as\nevidence against her)"}},{"id":"file.readme-first","kind":"document","name":"readme 1st.txt","icon":"doc","parentId":"folder.c","meta":{"createdAt":"1997-06-30","modifiedAt":"1997-06-30","sizeKb":1,"desktop":{"x":312,"y":24}},"body":{"text":"casey —\ngot your computer hooked back up after the move. new house, same\nrules: don''t install junk off the web, and if the modem does the\nscreechy thing, unplug it, count to ten, act natural.\n— J\n\nps. change your password. i guessed it in one try. ONE."}},{"id":"photo.fair","kind":"photo","name":"fair_ferris_aug97.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-08-23","sizeKb":84,"caption":"county fair w/ sadie + angel. angel lost her churro on this ride.","photoSrc":"/photos/fair_ferris_aug97.jpg"}},{"id":"photo.lockers","kind":"photo","name":"me_and_sadie_lockers.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-09-05","sizeKb":71,"caption":"first week of junior year. sadie decorated my locker. it is SO much.","photoSrc":"/photos/me_and_sadie_lockers.jpg"}},{"id":"photo.buster","kind":"photo","name":"buster_box.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-04-19","sizeKb":66,"caption":"buster claims another box. the box was for him actually.","photoSrc":"/photos/buster_box.jpg"}},{"id":"photo.river","kind":"photo","name":"river_last_swim.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-08-31","sizeKb":90,"caption":"the bend out route 9, last swim of summer. dad''s spot. six skips, still my record.","photoSrc":"/photos/river_last_swim.jpg"}},{"id":"photo.garage","kind":"photo","name":"garage_band.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-06-14","sizeKb":77,"caption":"sadie''s cousin''s band practicing. they are not good. do not tell them.","photoSrc":"/photos/garage_band.jpg"}},{"id":"photo.sweet16","kind":"photo","name":"sweet16_cake.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-04-12","sizeKb":82,"caption":"mom made the cake herself. it leaned. we loved it. (before the wedding, before everything.)","photoSrc":"/photos/sweet16_cake.jpg"}},{"id":"photo.at-computer","kind":"photo","name":"me_deep_in_cyberspace.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-09-20","sizeKb":88,"caption":"sadie burst in and took this ''for posterity.'' me and the beast, deep in cyberspace.","photoSrc":"/photos/casey_at_computer.jpg"}},{"id":"photo.sunflowers","kind":"photo","name":"moms_sunflowers.gif","icon":"photo","parentId":"folder.pictures","meta":{"createdAt":"1997-08-10","sizeKb":74,"caption":"mom''s sunflowers got taller than the fence this year. she''s unbearable about it.","photoSrc":"/photos/moms_sunflowers.jpg"}},{"id":"mailbox.inbox","kind":"mailbox","name":"Inbox","icon":"mailbox"},{"id":"mailbox.sent","kind":"mailbox","name":"Sent","icon":"mailbox"},{"id":"mailbox.deleted","kind":"mailbox","name":"Deleted","icon":"mailbox-trash"},{"id":"email.mom.dinner","kind":"email","name":"dinner + this weekend","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"Leslie Wright <lwright@westwind.net>","to":"casey_t@westwind.net","date":"1997-10-09T17:41:00"},"body":{"text":"Casey - Jon and I are at the Hendersons'' until late, there''s leftover\ncasserole in the fridge, the GOOD tupperware not the mystery one in\nthe back. Feed Buster. Homework before computer, I mean it, the phone\nbill was $$$ last month.\n\nAlso your father called the house again. I know, I know. Just - if\nyou want to see him this weekend that''s fine, tell me first, ok?\n\nLove you. Mom"}},{"id":"email.school.newsletter","kind":"email","name":"WILDCAT WEEKLY - Week of Oct 6","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"Franklin Walker Community High <office@fwch.k12.wv.net>","to":"students@fwch.k12.wv.net","date":"1997-10-08T09:00:00"},"body":{"text":"THE WILDCAT WEEKLY — Franklin Walker Community High — Oct 6, 1997\n\n* FALL SPORTS: Varsity football falls to Man 21-14. JV volleyball\n  hosts Logan Thursday.\n* PICTURE RETAKES are October 21. Forms in the front office.\n* The HOMECOMING DANCE is October 25 in the main gym. Theme:\n  \"A Night Under the Stars.\" Tickets $5 at lunch.\n* REMINDER: The fire road off Route 9 past mile marker 6 is COUNTY\n  PROPERTY and closed after dusk. Violators will be cited.\n* Chess club needs members. Seriously. Anyone. Please."}},{"id":"email.angel.chain","kind":"email","name":"FW: FW: FW: THE GOOD LUCK ANGEL!!!","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"angel jackson <angeljx@westwind.net>","to":"casey_t@westwind.net","date":"1997-10-07T20:14:00"},"body":{"text":">>> SEND TO 10 FRIENDS IN 24 HOURS OR ELSE <<<\n\nok 1) it has my NAME on it so it''s basically legally binding and\n2) marcy t. of ohio''s modem got struck by LIGHTNING casey. i''m not\ntaking chances and neither should you.\n\n(also fair pics came back from the developer. you look cute, i look\nlike i''m being arrested.)\n\nxoxo angel"}},{"id":"email.fanclub.digest","kind":"email","name":"SOLAR FLARE FAN CIRCLE - Digest #44","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"Solar Flare Fan Circle <circle@solarflareband.net>","to":"circle@solarflareband.net","date":"1997-10-06T06:30:00"},"body":{"text":"SOLAR FLARE FAN CIRCLE — DIGEST #44\n\n1) TOUR DATES CONFIRMED (see the website for the full list!)\n2) StaticHeartGrrl asks: is the hidden track on side B real or a\n   pressing error? (17 replies. it''s getting heated.)\n3) Trade board: HUNTINGTON 96 bootleg tape, looking for the acoustic\n   radio session. No rippers this time please.\n\nTo unsubscribe, reply UNSUBSCRIBE. (This has never once worked.)"}},{"id":"email.westwind.notice","kind":"email","name":"WestWind Mail: Your mailbox is 80% full","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"WestWind Online <postmaster@westwind.net>","to":"casey_t@westwind.net","date":"1997-10-03T04:00:00"},"body":{"text":"Dear WestWind Member,\n\nYour mailbox (casey_t) is at 80% of its 2 MB storage limit. To avoid\nmissed messages, please delete old mail or upgrade to WestWind GOLD\nfor just $4.95/month and enjoy a spacious 10 MB.\n\nWestWind Online — \"Your Window to the World Wide Web\"\nMember Services | Dial-up Support: 1-800-555-0134"}},{"id":"email.chad.sorry","kind":"email","name":"im sorry ok","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"chad daniels <bigchad4x4@westwind.net>","to":"casey_t@westwind.net","date":"1997-10-10T18:02:00"},"body":{"text":"ok so that went bad. i shouldnt of grabbed your arm like that in\nfront of everybody. im sorry. i mean it.\n\nbut casey you gotta see it from where im standing. every nite this\nweek your line is busy till 2am. angel says your \"on the computer.\"\ntalking to WHO. you wont say. you go all quiet when i ask. what am i\nsuposed to think.\n\nwhatever it is just tell me. even if its bad. im at genes with the\nguys tonite, dont wanna sit home mad. call the bar if you want, ask\nfor me.\n\n- c"}},{"id":"email.sadie.please","kind":"email","name":"please write back","icon":"mail","parentId":"mailbox.inbox","onOpen":{"discover":["the-meeting"]},"meta":{"from":"Sadie Thompson <sadiedraws77@westwind.net>","to":"casey_t@westwind.net","date":"1997-10-11T16:22:00"},"body":{"text":"casey.\n\ni don''t even know why i''m writing this. maybe you''ll dial in from\nsomewhere and see it. maybe your mom will. i don''t know.\n\nthe police talked to me AGAIN today. i told them what i told them\nbefore. thursday night on the porch you said you were meeting\nsomeone friday. down by the river. \"it''s a whole thing, i''ll tell\nyou saturday.\" you were EXCITED, casey. and scared. both at once. i\nshould have made you tell me. i keep thinking if i''d just made you\ntell me.\n\nyou don''t do things like this. you don''t just GO somewhere at night\nand not tell me who. you tell me everything. you have told me\neverything since second grade.\n\nso either you didn''t know who it was either. or you thought you did.\n\nplease just write back. i''m not even mad. i just want you to write\nback.\n\n- s"}},{"id":"email.church.prayer","kind":"email","name":"Prayer chain for the Taylor family","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"Grace Fellowship Hall <fellowship@gracewv.net>","to":"congregation@gracewv.net","date":"1997-10-13T08:15:00"},"body":{"text":"Dear friends,\n\nPlease hold Leslie, Jonathan, and Frank, and all who love Casey, in\nyour prayers this week. The sheriff''s office asks volunteers for the\nsearch to meet at the Route 9 trailhead at 7 AM Saturday, dress warm.\n\nFather Mike at St. Mark''s will hold a joint vigil Friday evening —\nall denominations welcome, which he asked us to underline twice.\n\nCasseroles can be left with Dorothy. She has a system.\n\nIn faith,\nGrace Fellowship Hall"}},{"id":"email.angel.sorry","kind":"email","name":"(no subject)","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"angel jackson <angeljx@westwind.net>","to":"casey_t@westwind.net","date":"1997-10-14T23:40:00"},"body":{"text":"i told them the truth today. the real one. i know it looks bad that\ni changed it. i KNOW.\n\ni said i dropped you home at 8 because if i said we were out back of\ngene''s my cousin loses his job and probably worse, and my mom -- you\nknow how my mom is. it didn''t seem like it MATTERED, you were HOME\nafter, i watched you walk in.\n\nnow everybody looks at me in the hall like i did something. sadie\nwon''t hardly talk to me.\n\nwherever you are i''m sorry. i''d take it back. the wine coolers were\nwarm anyway.\n\n- a"}},{"id":"email.sadie.notchad","kind":"email","arrivesOnline":true,"name":"it’s not chad","icon":"mail","parentId":"mailbox.inbox","requires":{"discovery":"stolen-intimacy"},"onOpen":{"discover":["chads-window"]},"meta":{"from":"Sadie Thompson <sadiedraws77@westwind.net>","to":"casey_t@westwind.net","date":"1997-10-15T21:03:00"},"body":{"text":"they took chad in again today. third time. half the school has him\nconvicted because of the parking lot thing and because he''s, well,\nchad.\n\nbut casey, listen. it''s not him. and i can prove it with his own\nstupid jealousy.\n\nthat whole last week he kept cornering ME. \"who''s she talking to at\n2am. is it a guy from man? is it somebody from charleston?\" he was\nOBSESSED with who you were talking to online. begging me to tell him.\n\nif chad was the one talking to you, what was he jealous OF?\n\nwhoever it was, it was somebody who didn''t need to ask me anything.\nsomebody who already knew things. and that list is so short it''s\nbasically just me. and it wasn''t me.\n\ni''m going to keep pulling on this even if nobody listens to a fat\ngirl with a sketchbook. watch me.\n\n- s"}},{"id":"email.ruth.yourdad","kind":"email","arrivesOnline":true,"name":"about your daddy","icon":"mail","parentId":"mailbox.inbox","requires":{"discovery":"chads-window"},"onOpen":{"discover":["the-clean-truck"]},"meta":{"from":"Ruth Taylor Combs <rcombs@westwind.net>","to":"casey_t@westwind.net","date":"1997-10-16T19:20:00"},"body":{"text":"Casey honey, it''s your Aunt Ruth. I don''t know who reads this now.\nMaybe nobody. I''m writing it anyway because somebody in this county\nought to write down the truth someplace.\n\nThey keep saying your daddy''s name in town like a verdict. Because\nit''s his road. Because he drinks. Because he''s Frank.\n\nHere is what my brother told me, and Frank Taylor has never once\nlied to me in fifty years: Friday night he was on his porch. Around\nten he watched a vehicle come up the fire road and stop at the bend.\nA DARK 4x4, CLEAN, quiet, newer. Sat there with the lights off.\n\nHoney, your daddy can name every engine in this county with his eyes\nshut. He said, and I quote, \"It wasn''t the Daniels boy. That truck of\nhis you can hear from the church. This one was somebody who washes\nhis car.\"\n\nHe won''t tell the sheriff. He''d been drinking and he''s got the old\ntrouble on his record and he is CERTAIN they''ll twist it on him. He\ntold me instead. Now I''ve told you, whoever you are.\n\nSomebody who washes his car. In this town that''s a short list too.\n\nAunt Ruth"}},{"id":"email.sam.question","kind":"email","name":"you asked me a question","icon":"mail","parentId":"mailbox.inbox","meta":{"from":"Samuel Reed <sreed@reedsdrug.westwind.net>","to":"casey_t@westwind.net","date":"1997-10-17T08:05:00"},"body":{"text":"Dear Casey,\n\nTwo weeks ago you stood at my counter and asked me, very carefully,\n\"if a doctor writes too many prescriptions, who checks?\" I gave you\nthe short answer. The state board. I should have given you the long\none, which is: nobody, child. Nobody checks. That is the whole\nproblem and you had already figured it out.\n\nI am forwarding below the letter I sent the Board of Pharmacy in\nSeptember. They have not answered. I no longer expect them to.\n\nI don''t know what you found or where you were going with it. But I\nhave been fifty-eight years in this town, and I know that a girl\nasked me the right question and eight days later she was gone.\n\nIf anyone reads this who loves her: look after what she was carrying.\n\n- Sam Reed\n\n> To the WV Board of Pharmacy: I write regarding a pattern of\n> scheduled-narcotic prescriptions originating from a single local\n> practice and filled at a single local pharmacy, in volumes that in\n> forty years of practice I have never...\n> [letter continues]"}},{"id":"email.sam.plain","kind":"email","arrivesOnline":true,"name":"what i should have said","icon":"mail","parentId":"mailbox.inbox","requires":{"discovery":"the-clean-truck"},"onOpen":{"discover":["the-pipeline"]},"meta":{"from":"Samuel Reed <sreed@reedsdrug.westwind.net>","to":"casey_t@westwind.net","date":"1997-10-18T07:12:00"},"body":{"text":"Dear Casey,\n\nI wrote to you yesterday and I have not slept since. I was careful in\nthat letter. Fifty-eight years in this town teaches you careful like\na trade. I am done with it.\n\nHere is what I know, plainly, and I will say it to any officer of\nthe law who finally asks.\n\nSince March, one local practice has written more scheduled-narcotic\nprescriptions than the rest of this county combined. Nearly all of\nthem are filled at one pharmacy — not mine. The patients pay cash.\nThe plates out front are from three counties away. Saturday hours,\nfrom a doctor who wouldn''t open on a Saturday for a heart attack ten\nyears running.\n\nA pharmacist who fills a script isn''t required to ask why. A doctor\nwho writes one isn''t required to answer. That is the machine, and it\nruns on nobody-checks.\n\nYou stood at my counter and asked me who checks. You already knew,\ndidn''t you. You had found something, and you were deciding who was\nsafe to hand it to.\n\nWhoever reads this: she was sixteen, and she was the only one in\nthis county doing my job. Look at where the money goes.\n\n- Sam Reed"}},{"id":"email.rebecca","kind":"email","arrivesOnline":true,"name":"to whoever is going through her things","icon":"mail","parentId":"mailbox.inbox","requires":{"discovery":"the-pipeline"},"onOpen":{"discover":["who-shaped"]},"meta":{"from":"R. Wright <rwright@mailhouse.net>","to":"casey_t@westwind.net","date":"1997-10-16T23:55:00"},"body":{"text":"I don''t know who reads a missing girl''s mail. Her mother, maybe.\nThe police, if anyone made them. I am counting on it being somebody.\n\nMy name is Rebecca Wright. I was married to Jonathan Wright for six\nyears. I read about the girl in the Register. I saw his name in the\nlist of family. I have started this letter four times.\n\nI will just say it plain.\n\nWhen we were married, Jonathan read my mail. All of it. I found out\nbecause he ANSWERED some of it. As me. My own cousin got letters in\nmy voice for a year — my phrases, my jokes, things only I would\nknow — and never suspected, because Jonathan pays attention. It is\nthe only thing he truly does. He pays attention, and then he becomes\nthe person you trust.\n\nWhen I finally left he told me, calm as church, that no one would\nbelieve me. For six years no one did.\n\nIf that girl trusted somebody she shouldn''t have, ask how that\nsomebody knew what to say.\n\nAsk him about my mail. 1989 to 1991. Ask him.\n\nR.W."}},{"id":"email.sent.sadie","kind":"email","name":"re: porch tonight?","icon":"mail","parentId":"mailbox.sent","meta":{"from":"casey_t@westwind.net","to":"Sadie Thompson <sadiedraws77@westwind.net>","date":"1997-10-09T21:58:00"},"body":{"text":"> porch? i have twizzlers and a new theory about the vice principal\n\ncan''t tonight - busy online. tell you about it saturday. all of it,\ni promise. it''s kind of a big thing and i want to be SURE first.\n\nsaturday. porch. bring the twizzlers.\n\n- c"}},{"id":"email.sent.mom","kind":"email","name":"re: dinner + this weekend","icon":"mail","parentId":"mailbox.sent","meta":{"from":"casey_t@westwind.net","to":"Leslie Wright <lwright@westwind.net>","date":"1997-10-09T18:03:00"},"body":{"text":"yes i fed buster. yes the good tupperware. and yeah - tell dad\nmaybe sunday? i kind of want to see him.\n\nthe phone bill is not my fault, tell your husband the modem is FOR\nthe phone line, that''s the whole point of it.\n\nlove you, bye, i''m fine"}},{"id":"email.deleted.coupon","kind":"email","name":"SAVE BIG at Compu-Barn! October Blowout","icon":"mail","parentId":"mailbox.deleted","meta":{"from":"Compu-Barn Superstore <deals@compubarn.net>","to":"casey_t@westwind.net","date":"1997-10-02T12:00:00"},"body":{"text":"COMPU-BARN OCTOBER BLOWOUT! 56K modems from $89! Blank 3.5\" disks\n10-pack: $4.99! Ink cartridges (ask an associate)! Compu-Barn: We''re\nPractically Giving It Away (Legal: we are not giving it away.)"}},{"id":"im.sadie","kind":"im_conversation","name":"sadiedraws77","icon":"im","meta":{"screenname":"sadiedraws77","alias":"sadie","logDate":"1997-10-03"},"body":{"messages":[{"from":"sadiedraws77","at":"9:02 PM","text":"ur mom said yes to the sleepover right"},{"from":"SunflwrC81","at":"9:02 PM","text":"yes. jon said \"as long as your homework is done\" like he''s my dad"},{"from":"sadiedraws77","at":"9:03 PM","text":"ugh. ok bring the fair pics"},{"from":"SunflwrC81","at":"9:03 PM","text":"and MY radio. yours eats tapes"},{"from":"sadiedraws77","at":"9:04 PM","text":"it ate ONE tape ONE time"},{"from":"sadiedraws77","at":"9:07 PM","text":"hey serious second. u seemed weird at lunch. weird-weird not tired-weird"},{"from":"SunflwrC81","at":"9:08 PM","text":"i''m ok. theres just. stuff at the house. i''ll tell u when i''m sure"},{"from":"sadiedraws77","at":"9:08 PM","text":"ok new rule. if it ever gets Actually Bad u say junebug and i come get u. no questions. day or night"},{"from":"SunflwrC81","at":"9:09 PM","text":"junebug?? why junebug"},{"from":"sadiedraws77","at":"9:09 PM","text":"first thing i ever drew that looked like the thing. second grade. u kept it"},{"from":"SunflwrC81","at":"9:10 PM","text":"i still have it somewhere. ok. junebug. deal."},{"from":"sadiedraws77","at":"9:10 PM","text":"deal. and nobody else EVER gets that word. it''s ours"},{"from":"SunflwrC81","at":"9:11 PM","text":"ours. gnight weirdo"},{"from":"sadiedraws77","at":"9:11 PM","text":"gnight. saturday!!"}]}},{"id":"im.angel","kind":"im_conversation","name":"AngelJx","icon":"im","meta":{"screenname":"AngelJx","alias":"angel","logDate":"1997-10-09"},"body":{"messages":[{"from":"AngelJx","at":"7:02 PM","text":"tomorrow after school. my cousin''s working the back lot at gene''s 👀"},{"from":"SunflwrC81","at":"7:04 PM","text":"angel. it''s a school night for ur cousin''s JOB"},{"from":"AngelJx","at":"7:04 PM","text":"it''s friday tomorrow. live a little. u need it, u''ve been a GHOST all week"},{"from":"SunflwrC81","at":"7:06 PM","text":"ok fine. but i have to be home by 7. i have a thing later"},{"from":"AngelJx","at":"7:06 PM","text":"what thing"},{"from":"SunflwrC81","at":"7:07 PM","text":"a thing thing. tell u after"},{"from":"AngelJx","at":"7:07 PM","text":"ur so mysterious lately. fine. 3:30, don''t wear the church shoes"},{"from":"SunflwrC81","at":"7:08 PM","text":"ONE time. gtg someone msgd me"},{"from":"AngelJx","at":"7:08 PM","text":"ooooooo. TELL ME AFTER"}]}},{"id":"folder.recycle","kind":"folder","name":"Recycle Bin","icon":"trash","fullWhenHasChildren":"folder.recycle"},{"id":"trash.essay-draft","kind":"trash_item","name":"minewars_draft1.txt","icon":"doc","parentId":"folder.recycle","meta":{"deletedAt":"1997-10-08","originalPath":"C:\\My Documents\\School","sizeKb":2},"body":{"text":"The Mine Wars\nby Casey Taylor\n\nThe Mine Wars were a series of wars that happened in the mines\n\n[the rest of the page is blank. a strong start.]"}},{"id":"trash.old-wallpaper","kind":"trash_item","name":"old_wallpaper.gif","icon":"photo","parentId":"folder.recycle","meta":{"deletedAt":"1997-09-12","originalPath":"C:\\Pictures","sizeKb":120,"caption":"(a tiled pattern of cartoon suns. it was a phase.)","photoSrc":"/photos/old_wallpaper.jpg"}},{"id":"trash.bl-log","kind":"trash_item","name":"bl_log_ghstbrdg.txt","icon":"doc","parentId":"folder.recycle","requires":{"discovery":"the-meeting"},"onOpen":{"discover":["stolen-intimacy"]},"meta":{"deletedAt":"1997-10-10","originalPath":"C:\\Program Files\\Chat\\logs","sizeKb":2},"body":{"text":"[BuddyLine saved log — GhostBridge — 10/10/97]\n\nGhostBridge: is the page somewhere safe\nSunflwrC81: yes. ok my turn. you say you''ve been building a case on\n  him for two years. you know things. FINE. but i still don''t know\n  you''re not just some guy\nGhostBridge: what would make you sure\nSunflwrC81: i don''t know. something real\nGhostBridge: alright. tonight, when we meet — if you feel unsafe at\n  any point, say junebug, and i''ll know it''s really you and get you\n  out of there.\nSunflwrC81: ...\nSunflwrC81: how do you know that word\nGhostBridge: i know a lot of things, casey. that''s the job. it''s how\n  i knew about sparks before you did.\nSunflwrC81: nobody knows that word. two people on EARTH know that\n  word\nGhostBridge: and now a third, who is on your side. the bend. ten\n  o''clock. bring the page. come alone — not the boyfriend, not\n  sadie. and delete these logs, all of them. if he finds out you\n  talked, everything gets worse.\nSunflwrC81: this is crazy. ok. ok. ten.\nGhostBridge: good girl. it will all be over after tonight.\nSunflwrC81: that''s a weird way to say it\nGhostBridge: goodnight casey\nSunflwrC81: hello?\nSunflwrC81: hello??"}},{"id":"trash.diary","kind":"trash_item","name":"diary.doc","icon":"doc","parentId":"folder.recycle","requires":{"discovery":"who-shaped"},"onOpen":{"discover":["the-house"]},"meta":{"deletedAt":"1997-10-11","modifiedAt":"1997-10-11","originalPath":"C:\\My Documents\\personal stuff","sizeKb":1},"body":{"text":"[file partially recovered — most sectors overwritten]\n\n...g 9 — found an envelope of cash in J''s good coat looking for the\ntruck keys. like, a LOT of cash. probably nothing. probably...\n\n...bottle in the glovebox with some stranger''s name on...\n\n...ct 5 — got the page from the desk in the den. copied it. put it\nback EXACT. my hands were shak...\n\n...8 — he knew junebug. HOW. i keep coming back to it. only me and\ns. on the whole ea...\n\n...doesn''t matter. if GB can put sparks away then whoever he is,\nhe''s the only adult actually DOING someth...\n\n...ay night. after tomorrow i tell sadie everything and it''s over\nand things go back to nor\n\n[end of recovered data]\n\n[properties — diary.doc]\n  created:   06/02/96\n  modified:  10/11/97  2:14 AM\n  deleted:   10/11/97  2:14 AM\n  last user: this machine"}},{"id":"shortcut.mail","kind":"shortcut","name":"Mail","icon":"mail-app","meta":{"appId":"mail","desktop":{"x":120,"y":120}}},{"id":"shortcut.buddyline","kind":"shortcut","name":"Chat","icon":"im-app","meta":{"appId":"buddyline","desktop":{"x":120,"y":216}}},{"id":"shortcut.browser","kind":"shortcut","name":"NetVoyager","icon":"browser","meta":{"appId":"browser","desktop":{"x":120,"y":24}}},{"id":"shortcut.notepad","kind":"shortcut","name":"Notepad","icon":"notepad","meta":{"appId":"notepad","desktop":{"x":216,"y":24}}},{"id":"shortcut.solitaire","kind":"shortcut","name":"Solitaire","icon":"game","meta":{"appId":"solitaire","desktop":{"x":216,"y":120}}},{"id":"shortcut.dialup","kind":"shortcut","name":"WestWind Online","icon":"dialup","meta":{"appId":"dialup","desktop":{"x":216,"y":216}}},{"id":"shortcut.recycle","kind":"shortcut","name":"Recycle Bin","icon":"trash","fullWhenHasChildren":"folder.recycle","meta":{"appId":"recycle","desktop":{"x":24,"y":408}}},{"id":"folder.bookmarks","kind":"folder","name":"Bookmarks","icon":"folder"},{"id":"bm.searchhound","kind":"bookmark","name":"SearchHound","parentId":"folder.bookmarks","meta":{"url":"www.searchhound.net"}},{"id":"bm.mypage","kind":"bookmark","name":"my page!!","parentId":"folder.bookmarks","meta":{"url":"www.citypages.net/~sunflwrc81"}},{"id":"bm.sadiepage","kind":"bookmark","name":"sadie''s page","parentId":"folder.bookmarks","meta":{"url":"www.citypages.net/~sadiedraws77"}},{"id":"bm.solarflare","kind":"bookmark","name":"SOLAR FLARE official","parentId":"folder.bookmarks","meta":{"url":"www.solarflareband.net"}},{"id":"bm.register","kind":"bookmark","name":"Humble Register","parentId":"folder.bookmarks","meta":{"url":"www.humbleregister.net"}},{"id":"bm.citypages","kind":"bookmark","name":"CityPages directory","parentId":"folder.bookmarks","meta":{"url":"www.citypages.net"}},{"id":"web.searchhound","kind":"webpage","name":"SearchHound","meta":{"url":"www.searchhound.net","siteTitle":"SearchHound — Fetch the Web!"},"searchText":"search engine directory web","body":{"style":{"bg":"#ffffff","fg":"#000000","link":"#0000cc","font":"serif","centered":true},"blocks":[{"t":"img","caption":"SearchHound — Fetch the Web","src":"/web/searchhound_logo.svg"},{"t":"searchform"},{"t":"small","text":"Tip: To find a person''s home page, put their name in quotes: \"casey taylor\". To require a word, put + in front of it. Rex ignores the + but appreciates the effort."},{"t":"hr"},{"t":"p","text":"SearchHound indexes 4,081,226 pages found on 21,407 servers, refreshed nightly by our tireless crawler, Rex. Rex is very proud of this and would like you to know."},{"t":"small","text":"Or browse by topic: Arts & Entertainment · Computers & Internet · News & Media · Recreation · Regional: Appalachia · Society & Culture"},{"t":"hr"},{"t":"small","text":"Surprise · Add URL · Help · Feedback — SearchHound is a service of Meridian Digital Systems. Best viewed at 800x600 in NetVoyager 3.0 or later."},{"t":"counter","value":4088211}]}},{"id":"web.casey-page","kind":"webpage","name":"casey''s corner of the web","meta":{"url":"www.citypages.net/~sunflwrc81","siteTitle":"~*~ casey''s corner ~*~"},"searchText":"casey taylor humble personal homepage sunflower","body":{"style":{"bg":"#000033","fg":"#ffffcc","link":"#66ffff","font":"sans","centered":true,"accent":"#ff66cc"},"blocks":[{"t":"h","text":"~*~ welcome to casey''s corner ~*~"},{"t":"marquee","text":"you are visitor number one zillion. under construction FOREVER."},{"t":"img","caption":"[ spinning sunflower gif ]"},{"t":"p","text":"hi i''m casey. 16. humble west virginia (if you know where that is i''m so sorry). i like: solar flare, my cat buster, the river, writing stories i never finish, my friends."},{"t":"p","text":"i dislike: algebra, chain letters (ANGEL), when the modem drops you at 11:58 pm, people who ask what my dad is up to."},{"t":"hr"},{"t":"sub","text":"cool links"},{"t":"link","text":"SOLAR FLARE official site","url":"www.solarflareband.net"},{"t":"link","text":"sadie''s page (actual art on it, not like mine)","url":"www.citypages.net/~sadiedraws77"},{"t":"link","text":"the CityPages member directory (find ur neighbors)","url":"www.citypages.net"},{"t":"link","text":"SearchHound","url":"www.searchhound.net"},{"t":"hr"},{"t":"small","text":"sign my guestbook!! (guestbook broken since june. it counts the thought.)"},{"t":"counter","value":1204}]}},{"id":"web.sadie-page","kind":"webpage","name":"sadie draws (sometimes)","meta":{"url":"www.citypages.net/~sadiedraws77","siteTitle":"sadie draws (sometimes)"},"searchText":"sadie thompson art sketches drawing humble","body":{"style":{"bg":"#f4f0e4","fg":"#333322","link":"#886600","font":"sans","centered":true},"blocks":[{"t":"h","text":"sadie draws (sometimes)"},{"t":"small","text":"a page for my sketches. casey made me put them up. blame her."},{"t":"img","caption":"[ scanned sketch: a girl on a porch, done in ballpoint. it''s good. it''s really good. ]"},{"t":"img","caption":"[ scanned sketch: a junebug, second-grade style, kept for sentimental reasons ]"},{"t":"list","items":["things i draw: people who don''t know i''m drawing them","things i won''t draw: your boyfriend, stop asking","currently reading: everything true-crime the library has"]},{"t":"hr"},{"t":"small","text":"last updated october 4 1997. (probably a while ago now, whenever you''re reading this.)"},{"t":"counter","value":312}]}},{"id":"web.solarflare","kind":"webpage","name":"SOLAR FLARE official","meta":{"url":"www.solarflareband.net","siteTitle":"SOLAR FLARE — official site"},"searchText":"solar flare band static heart tour music","body":{"style":{"bg":"#110011","fg":"#ffcc00","link":"#ff6600","font":"sans","centered":true},"blocks":[{"t":"h","text":"SOLAR FLARE"},{"t":"sub","text":"new album \"STATIC HEART\" out now on Meridian Records"},{"t":"img","caption":"[ band photo: four people refusing to smile ]"},{"t":"p","text":"FALL TOUR ON SALE NOW. Charleston, Huntington, Morgantown, Roanoke. All ages except Roanoke (sorry, Roanoke)."},{"t":"link","text":"join the FAN CIRCLE mailing list","url":"www.solarflareband.net"},{"t":"hr"},{"t":"small","text":"webmaster: dennis. yes the drummer. no i will not fix the guestbook."}]}},{"id":"web.register","kind":"webpage","name":"The Humble Register","meta":{"url":"www.humbleregister.net","siteTitle":"The Humble Register — Online Edition"},"searchText":"humble register news casey taylor missing search route 9 river bend","body":{"style":{"bg":"#ffffff","fg":"#111111","link":"#0000aa","font":"serif"},"blocks":[{"t":"h","text":"The Humble Register"},{"t":"small","text":"Online Edition — Updated Wednesdays (usually) — Oct. 15, 1997"},{"t":"hr"},{"t":"sub","text":"SEARCH FOR MISSING TEEN ENTERS SECOND WEEK"},{"t":"p","text":"The search for Casey Taylor, 16, of Humble, continued this week with volunteers walking the fire roads along the river. Taylor was last seen the evening of Friday, Oct. 10. Her bicycle was recovered near the Route 9 trailhead the following morning."},{"t":"p","text":"Sheriff Dale Purvis urged residents with information to come forward. \"Somebody saw something,\" Purvis said. \"In a county this size, somebody always has.\""},{"t":"p","text":"A joint vigil is planned Friday evening at St. Mark''s. The family has asked for privacy. Value-Med Discount Pharmacy has donated flashlights and batteries for the volunteer search teams."},{"t":"hr"},{"t":"sub","text":"ALSO THIS WEEK"},{"t":"list","items":["County board delays Route 9 guardrail project a third time","Wildcats fall to Man 21-14; Logan up next","Harvest Festival parking: what to know (bring quarters)"]},{"t":"link","text":"SPECIAL REPORT: A timeline of Friday, Oct. 10 — what we can pin down","url":"www.humbleregister.net/timeline"},{"t":"hr"},{"t":"small","text":"The Register Online is a service of Humble Printing & Copy. Story tips: tips@humbleregister.net"}]}},{"id":"web.register-timeline","kind":"webpage","name":"The Humble Register: Timeline of Oct. 10","meta":{"url":"www.humbleregister.net/timeline","siteTitle":"The Humble Register — A Timeline of Friday, Oct. 10"},"searchText":"chad daniels timeline genes bar alibi barstool last day friday october 10 casey taylor","requires":{"discovery":"stolen-intimacy"},"onOpen":{"discover":["chads-window"]},"body":{"style":{"bg":"#ffffff","fg":"#111111","link":"#0000aa","font":"serif"},"blocks":[{"t":"h","text":"The Humble Register"},{"t":"small","text":"Online Edition — SPECIAL REPORT, posted Oct. 17, 1997"},{"t":"hr"},{"t":"sub","text":"THE LAST DAY: WHAT WE CAN PIN DOWN"},{"t":"p","text":"The Register has assembled the following from public statements and our own interviews. Times are approximate except where noted."},{"t":"list","items":["3:30 PM — Franklin Walker lets out. Multiple students describe an argument in the parking lot between Casey Taylor and her boyfriend, Chad Daniels, 19.","4 to 7 PM — Taylor is with a friend; investigators say her movements in this window are now accounted for.","About 7 PM — Taylor is dropped off at home. A neighbor recalls seeing her at the mailbox.","6 PM to closing — Daniels is at Gene’s Bar. \"That boy was on the same stool from six until we shut the kitchen,\" said Earl Prater, who tends bar there. \"Used the bar phone twice trying to call the Taylor girl’s house. I dialed it for him the second time.\" The bar’s phone records are consistent with that account, the sheriff’s office confirmed Thursday.","About 9:50 PM — A resident along Route 9 reports hearing a single vehicle on the fire road. The report is unverified.","7:05 AM Saturday — Taylor’s bicycle is found at the Route 9 trailhead."]},{"t":"p","text":"Sheriff Dale Purvis declined to name any person of interest. \"Folks want it to be simple,\" Purvis said. \"Simple has an alibi.\""},{"t":"hr"},{"t":"small","text":"The Register Online is a service of Humble Printing & Copy. Story tips: tips@humbleregister.net"}]}},{"id":"web.mapfinder-bend","kind":"webpage","name":"MapFinder: Route 9 river bend","meta":{"url":"www.mapfinder.net/maps/route9-bend","siteTitle":"MapFinder — Route 9 River Bend"},"searchText":"mapfinder map route 9 river bend fire road mile marker 6 directions","requires":{"discovery":"the-meeting"},"body":{"style":{"bg":"#f4f4e8","fg":"#222222","link":"#006600","font":"sans"},"blocks":[{"t":"h","text":"MapFinder"},{"t":"small","text":"Maps for the Modern Motorist — beta"},{"t":"hr"},{"t":"sub","text":"Route 9 river bend — Humble County, WV"},{"t":"img","caption":"[ map tile: the river, fire road switchbacks past mile marker 6, a marked pull-off at the bend. one residence nearby: a parcel on the ridge above the road. ]"},{"t":"p","text":"Access via the county fire road off Route 9, past mile marker 6. Gate closed to vehicles after dusk; foot access is not patrolled. Approx. 20 minutes by bicycle from downtown Humble."},{"t":"small","text":"MapFinder cannot verify current road conditions. Print this page before travelling."}]}},{"id":"web.gen.sk8_or_dye","kind":"webpage","name":"Mr. Biscuit''s page","meta":{"url":"www.citypages.net/~sk8_or_dye","siteTitle":"The Official Home Page of Mr. Biscuit the cat"},"searchText":"Mr. Biscuit cat pet page sk8_or_dye","body":{"style":{"bg":"#ffeeee","fg":"#331111","link":"#990000","accent":"#cc3366","font":"sans","centered":true},"blocks":[{"t":"h","text":"Mr. Biscuit Online"},{"t":"small","text":"the official home page of Mr. Biscuit the cat. yes he has a web page. it''s 1997."},{"t":"img","caption":"[ Mr. Biscuit looking directly at the camera. majestic. ]"},{"t":"p","text":"he is 14 pounds of attitude and we love him"},{"t":"divider","kind":"dots"},{"t":"sub","text":"Mr. Biscuit''s likes:"},{"t":"list","items":["the vacuum (enemy)","ignoring commands","dinner","second dinner"]},{"t":"guestbook","count":47},{"t":